pureResponder.command:
node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {fixtureJudgment} from './responder.mjs';
import {fixtureSelection, COMMAND, SUPPORT, STAGE, REPAIR, STAGED_REPORT, REPAIRED_REPORT} from './workload.mjs';
const selected=await fixtureSelection();
assert.equal(selected.sources.length,3);
assert.equal(selected.sources.some(row=>row.path==='fixture/value.txt'),false);
assert.deepEqual(selected.request.workOrders.construction.writeRoots,['fixture/value.txt']);
assert.equal(selected.request.testing.commands.length,1);
assert.equal(selected.request.testing.commands[0].commandId,COMMAND);
const construction='graph-function://abiogenesis/default-library/construction@5';
const testing='graph-function://abiogenesis/default-library/testing@5';
const refs=['component-only:staged','component-only:red','component-only:repair','component-only:green'];
const schema={properties:{nextGraphFunctionRef:{enum:[construction,testing,null]},subjectEvidenceRef:{enum:[refs[0],refs[2],null]},nextEvidenceRefs:{items:{enum:refs}}}};
const stage={purpose:'construction',resultRef:refs[0],observed:{report:{summary:STAGED_REPORT}}};
const red={purpose:'testing',resultRef:refs[1],observed:{commandResults:[{commandId:COMMAND,exitStatus:1,timedOut:false,processSignal:null,stdout:{displayOnly:true,excerpts:[{startByte:0,endByte:54,text:'FIXTURE_VALUE_BAD expected=fixed actual="broken\\n"\n'}]}}]}};
const repair={purpose:'construction',resultRef:refs[2],observed:{report:{summary:REPAIRED_REPORT}}};
const green={purpose:'testing',resultRef:refs[3],observed:{commandResults:[{commandId:COMMAND,exitStatus:0,timedOut:false,processSignal:null,stdout:{encoding:'utf8',text:'FIXTURE_VALUE_FIXED\n'}}]}};
const prompt=observations=>'## task\n'+JSON.stringify({taskRef:selected.request.taskRef,unresolvedSupportRefs:[SUPPORT],observations,subjectEvidenceDomains:{testing:[refs[0],refs[2],null]}})+'\n\n## evidence\n{}';
const judge=(observations,mode='audit',carrier=schema)=>fixtureJudgment(prompt(observations),carrier,mode);
assert.equal(judge([],'basis').contributions[0].contribution,STAGE);
assert.equal(judge([stage],'basis').nextGraphFunctionRef,null);
assert.equal(judge([stage]).subjectEvidenceRef,refs[0]);
assert.equal(judge([stage,red]).contributions[0].contribution,REPAIR);
assert.match(judge([stage,red]).nextReason,/actual C2 exit 1/i);
assert.equal(judge([stage,red,repair]).subjectEvidenceRef,refs[2]);
const gap=judge([stage,red,repair,green]);
assert.equal(gap.nextGraphFunctionRef,null);
assert.equal(gap.subjectEvidenceRef,null);
assert.deepEqual(gap.gaps[0].supportRefs,[SUPPORT]);
assert.deepEqual(judge([stage,red,repair,green]),gap);
assert.throws(()=>judge([stage,{...red,observed:{commandResults:[{...red.observed.commandResults[0],exitStatus:2}]}}]),/Unexpected actual C2 failure/);
assert.throws(()=>judge([stage],'audit',{properties:{...schema.properties,nextGraphFunctionRef:{enum:[construction,null]}}}),/ineligible/);
const stream=[{type:'system',subtype:'init'},{type:'result',subtype:'success',is_error:false,result:JSON.stringify(gap),structured_output:gap}].map(row=>JSON.stringify(row)+'\n').join('');
assert.deepEqual(JSON.parse(stream.trim().split('\n')[1]).structured_output,gap);
console.log(JSON.stringify({disposition:'pass',cases:['source-and-scope-data','initial-construction','basis-gap','actual-domain-testing-selection','known-red-cause-before-repair','repaired-result-testing-selection','green-gap-no-acceptance','stateless-restart-decision','unexpected-red-refusal','ineligible-testing-refusal','structured-stream-framing'],premise:'Pure responder data checks with component-only refs; no runtime owner, worker process, native effect, Public setup or Run was executed.'}));
JS
